   225  static char *parse_proxy_protocol_v2(struct lwan_request *request, char *buffer)
   226  {
   227      struct proxy_header_v2 *hdr = (struct proxy_header_v2 *)buffer;
   228      struct lwan_request_parser_helper *helper = request->helper;
   229      const unsigned int proto_signature_length = 16;
   230      unsigned int size;
   231      struct lwan_proxy *const proxy = request->proxy;
   232
   233      enum { LOCAL = 0x20, PROXY = 0x21, TCP4 = 0x11, TCP6 = 0x21 };
   234
   235      size = proto_signature_length + (unsigned int)ntohs(hdr->len);
   236      if (UNLIKELY(size > (unsigned int)sizeof(*hdr)))
   237          return NULL;
   238      if (UNLIKELY(size >= helper->buffer->len))
   239          return NULL;
   240
   241      if (LIKELY(hdr->cmd_ver == PROXY)) {
   242          if (hdr->fam == TCP4) {
   243              struct sockaddr_in *from = &proxy->from.ipv4;
   244              struct sockaddr_in *to = &proxy->to.ipv4;
   245
   246              to->sin_family = from->sin_family = AF_INET;
   247
   248              from->sin_addr.s_addr = hdr->addr.ip4.src_addr;
   249              from->sin_port = hdr->addr.ip4.src_port;
   250
   251              to->sin_addr.s_addr = hdr->addr.ip4.dst_addr;
   252              to->sin_port = hdr->addr.ip4.dst_port;
   253          } else if (hdr->fam == TCP6) {
   254              struct sockaddr_in6 *from = &proxy->from.ipv6;
   255              struct sockaddr_in6 *to = &proxy->to.ipv6;
   256
   257              from->sin6_family = to->sin6_family = AF_INET6;
   258
   259              from->sin6_addr = hdr->addr.ip6.src_addr;
   260              from->sin6_port = hdr->addr.ip6.src_port;
   261
   262              to->sin6_addr = hdr->addr.ip6.dst_addr;
   263              to->sin6_port = hdr->addr.ip6.dst_port;
   264          } else {
   265              return NULL;
   266          }
   267      } else if (hdr->cmd_ver == LOCAL) {
   268          struct sockaddr_in *from = &proxy->from.ipv4;
   269          struct sockaddr_in *to = &proxy->to.ipv4;
   270
   271          from->sin_family = to->sin_family = AF_UNSPEC;
   272      } else {
   273          return NULL;
   274      }
